import type { ReactNode } from "react";
import { MenuHeader } from "@kerfjs/ui/menu-header";
import { MenuItem } from "@kerfjs/ui/menu-item";
import "@kerfjs/ui/layout.css";
import "./NavigationSidebar.css";

type Route = "overview" | "projects" | "members" | "billing";
export function NavigationSidebar({ current, onNavigate, onHelp, onSettings }: {
  current: Route; onNavigate: (route: Route) => void;
  onHelp: () => void; onSettings: () => void;
}) {
  const row = (id: Route, label: string, icon?: ReactNode, disabled = false) =>
    <MenuItem key={id} icon={icon} disabled={disabled}
      aria-current={current === id ? "page" : undefined}
      onClick={() => { if (!disabled) onNavigate(id); }}>{label}</MenuItem>;
  return <nav className="kui-layout kui-sidebar project-navigation" aria-label="Primary navigation">
    <div className="navigation-sections">
      <section className="kui-sidebar-section" aria-label="Workspace">
        <MenuHeader>Workspace</MenuHeader>
        {row("overview", "Overview", <span aria-hidden="true">⌂</span>)}
        {row("projects", "Projects")}
      </section>
      <section className="kui-sidebar-section" aria-label="Organization">
        <MenuHeader>Organization</MenuHeader>
        {row("members", "Members", <span aria-hidden="true">◎</span>)}
        {row("billing", "Billing (unavailable)", undefined, true)}
      </section>
      <section className="kui-sidebar-surface" aria-label="Workspace summary">
        <strong>Design workspace</strong>
        <p>12 projects · 8 members</p>
      </section>
    </div>
    <footer className="navigation-footer" aria-label="Workspace actions">
      <button type="button" onClick={onHelp}>Help</button>
      <button type="button" onClick={onSettings}>Settings</button>
    </footer>
  </nav>;
}

