.project-navigation { display: flex; flex-direction: column; min-height: 0; height: 100%; }
.navigation-sections { flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; }
.navigation-footer { display: flex; flex-wrap: wrap; gap: var(--kui-control-gap, .5rem); }
.navigation-footer button { min-height: 2.75rem; }
.navigation-footer :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
